import re

def parse_size(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError
    m = re.fullmatch(r'\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*', text)
    if not m:
        raise ValueError
    num = float(m.group(1))
    if num < 0:
        raise ValueError
    unit = m.group(2).lower()
    units = {
        'b': 1,
        'kb': 1000,
        'kib': 1024,
        'mb': 10**6,
        'mib': 2**20,
        'gb': 10**9,
        'gib': 2**30,
    }
    if unit not in units:
        raise ValueError
    return round(num * units[unit])

