def top_k_counts(words: list[str], k: int) -> list[tuple[str,int]]:
    if k <= 0:
        return []

    info = {}
    for idx, word in enumerate(words):
        key = word.lower()
        if key not in info:
            info[key] = (word, 1, idx)
        else:
            original, count, first_idx = info[key]
            info[key] = (original, count + 1, first_idx)

    sorted_items = sorted(info.values(), key=lambda x: (-x[1], x[2]))
    return [(item[0], item[1]) for item in sorted_items[:k]]
