import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    accum = {}

    for line in lines:
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except Exception:
            invalid += 1
            continue

        if not isinstance(obj, dict):
            invalid += 1
            continue

        if ('service' not in obj or not isinstance(obj['service'], str) or
            'latency_ms' not in obj or not isinstance(obj['latency_ms'], (int, float)) or isinstance(obj['latency_ms'], bool) or
            'status' not in obj or not isinstance(obj['status'], (int, float)) or isinstance(obj['status'], bool)):
            invalid += 1
            continue

        service = obj['service']
        latency = obj['latency_ms']
        status = obj['status']

        if service not in accum:
            accum[service] = {'latencies': [], 'ok': 0, 'total': 0}
        accum[service]['latencies'].append(latency)
        accum[service]['total'] += 1
        if 200 <= status < 300:
            accum[service]['ok'] += 1

    result = {"invalid": invalid}
    for service in sorted(accum.keys()):
        data = accum[service]
        n = data['total']
        ok_rate = data['ok'] / n if n > 0 else 0.0
        latencies = sorted(data['latencies'])
        if n == 0:
            p95 = None
        else:
            idx = math.ceil(0.95 * n) - 1
            p95 = latencies[idx]
        result[service] = {
            "count": n,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95
        }

    return result

import heapq
from collections import defaultdict

class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(str(cycle))

def dependency_plan(nodes: list[str], edges: list[tuple[str,str]]) -> list[str]:
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError

    unique_edges = set(edges)
    graph = defaultdict(set)
    indegree = {node: 0 for node in node_set}

    for a, b in unique_edges:
        graph[a].add(b)
        indegree[b] += 1

    heap = [node for node in node_set if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        curr = heapq.heappop(heap)
        result.append(curr)
        for nxt in graph[curr]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) == len(node_set):
        return result

    visited = set()
    path = []
    def dfs(u):
        path.append(u)
        visited.add(u)
        for v in sorted(graph[u]):
            if v in path:
                return path[path.index(v):] + [v]
            if v not in visited:
                cycle = dfs(v)
                if cycle:
                    return cycle
        path.pop()
        return None

    for node in sorted(node_set):
        if node not in visited and indegree[node] > 0:
            cycle = dfs(node)
            if cycle:
                raise CycleError(cycle)

    raise CycleError([])

