class _StreamingGroupSum:
    def __init__(self, rows):
        self._rows = rows
        self.invalid_count = 0
        self._processed = False
        self._results = []

    def _process(self):
        if self._processed:
            return
        totals = {}
        order = []
        for row in self._rows:
            try:
                if not isinstance(row, (list, tuple)) or len(row) != 3:
                    raise ValueError
                ts, key, val = row
                if not isinstance(val, (int, float)) or isinstance(val, bool):
                    raise ValueError
                if key not in totals:
                    totals[key] = 0
                    order.append(key)
                totals[key] += val
            except Exception:
                self.invalid_count += 1
        self._results = [(k, totals[k]) for k in order]
        self._processed = True

    def __iter__(self):
        self._process()
        for item in self._results:
            yield item


def streaming_group_sum(rows):
    return _StreamingGroupSum(rows)
