import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError
    last_exc = None
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            last_exc = e
            if attempt == attempts - 1 or not retry_if(e):
                break
            sleep(base_delay * 2 ** attempt)
    raise last_exc

import copy

def apply_patch_ops(document: dict, operations) -> dict:
    new_doc = copy.deepcopy(document)

    for op, path, value in operations:
        parts = path.split('.')

        if op == 'set':
            curr = new_doc
            for p in parts[:-1]:
                if not isinstance(curr, dict) or p not in curr:
                    raise ValueError(f"Path not found: {path}")
                curr = curr[p]
            if not isinstance(curr, dict):
                raise ValueError(f"Parent is not a dict: {path}")
            curr[parts[-1]] = value

        elif op == 'delete':
            curr = new_doc
            for p in parts[:-1]:
                if isinstance(curr, dict) and p in curr:
                    curr = curr[p]
                else:
                    curr = None
                    break
            if isinstance(curr, dict) and parts[-1] in curr:
                del curr[parts[-1]]

        elif op == 'increment':
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("Increment value must be int or float")
            curr = new_doc
            for p in parts[:-1]:
                if not isinstance(curr, dict) or p not in curr:
                    raise ValueError(f"Path not found: {path}")
                curr = curr[p]
            if not isinstance(curr, dict) or parts[-1] not in curr:
                raise ValueError(f"Path not found: {path}")
            if isinstance(curr[parts[-1]], bool) or not isinstance(curr[parts[-1]], (int, float)):
                raise ValueError(f"Value at path is not numeric: {path}")
            curr[parts[-1]] += value

        else:
            raise ValueError(f"Unsupported operation: {op}")

    return new_doc

