from concurrent.futures import Future

class IdempotentEventProcessor:
    def __init__(self, apply_callback):
        self._apply = apply_callback
        self._lock = threading.Lock()
        self._futures = {}

    def process(self, event_id, payload):
        with self._lock:
            fut = self._futures.get(event_id)
            if fut is None or (fut.done() and fut.exception() is not None):
                if fut is not None and fut.exception() is not None:
                    del self._futures[event_id]
                fut = Future()
                self._futures[event_id] = fut
                should_run = True
            else:
                should_run = False

        if should_run:
            try:
                result = self._apply(payload)
                fut.set_result(result)
            except Exception as e:
                fut.set_exception(e)
                with self._lock:
                    if self._futures.get(event_id) is fut:
                        del self._futures[event_id]

        return fut.result()

    def result(self, event_id):
        with self._lock:
            fut = self._futures.get(event_id)
            if fut is None or not fut.done() or fut.exception() is not None:
                raise KeyError(event_id)
            res = fut.result()
        return res

import threading

class BoundedQueue:
    def __init__(self, capacity):
        self._q = []
        self._cap = capacity
        self._closed = False
        self._cond = threading.Condition()

    def put(self, item):
        with self._cond:
            while len(self._q) >= self._cap and not self._closed:
                self._cond.wait()
            if self._closed:
                raise RuntimeError("Queue is closed")
            self._q.append(item)
            self._cond.notify()

    def get(self):
        with self._cond:
            while len(self._q) == 0 and not self._closed:
                self._cond.wait()
            if len(self._q) == 0:
                raise RuntimeError("Queue is closed and empty")
            item = self._q.pop(0)
            self._cond.notify()
            return item

    def close(self):
        with self._cond:
            if self._closed:
                return
            self._closed = True
            self._cond.notify_all()

