import copy

class VersionedStore:
    def __init__(self):
        self._lock = threading.Lock()
        self._data = {}
        self._versions = {}

    def read(self, key):
        with self._lock:
            if key not in self._data:
                return None
            return copy.deepcopy(self._data[key])

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            current_version = self._versions.get(key, 0)
            if current_version != expected_version:
                return False
            self._data[key] = copy.deepcopy(value)
            self._versions[key] = current_version + 1
            return True

    def delete(self, key, expected_version):
        with self._lock:
            current_version = self._versions.get(key, 0)
            if current_version != expected_version:
                return False
            self._data.pop(key, None)
            self._versions[key] = current_version + 1
            return True

    def snapshot(self):
        with self._lock:
            return copy.deepcopy(self._data)

class ReplicatedLog:
    def __init__(self):
        self._term = 0
        self._log = []
        self._commit = 0
        self._apply = 0

    def append(self, command):
        self._log.append({'term': self._term, 'command': command})
        return len(self._log)

    def receive_append(self, term, prev_index, prev_term, entries, leader_commit):
        if term < self._term:
            return False, 0
        if term > self._term:
            self._term = term
        if prev_index > len(self._log):
            return False, len(self._log) + 1
        if prev_index > 0 and self._log[prev_index - 1]['term'] != prev_term:
            return False, prev_index
        if entries:
            for i, entry in enumerate(entries):
                idx = prev_index + 1 + i
                if idx <= len(self._log):
                    if self._log[idx - 1]['term'] != entry['term']:
                        self._log = self._log[:idx - 1]
                        self._log.extend(entries[i:])
                        break
                else:
                    self._log.extend(entries[i:])
                    break
        if leader_commit > self._commit:
            self._commit = min(leader_commit, len(self._log))
        return True, len(self._log)

    def commit_to(self, index):
        if index > self._commit:
            self._commit = min(index, len(self._log))

    def apply_committed(self):
        if self._apply >= self._commit:
            return []
        cmds = [self._log[i]['command'] for i in range(self._apply, self._commit)]
        self._apply = self._commit
        return cmds

    def current_index(self):
        return len(self._log)

    def current_term(self):
        return self._term

